steps.solution:
function countGreetings(guests) {
  let greetings = 0
  for (let i = 0; i < guests.length; i++) {
    for (let j = 0; j < guests.length; j++) {
      if (i !== j) greetings = greetings + 1
    }
  }
  return greetings
}

console.log(countGreetings(['Ana', 'Ben', 'Cleo'])) // 6
